{"gameType":"stage-clear","input":"drag-follow","lang":"fr","loop":"Glissez le doigt autour de la tour pour tourner le faisceau et éclairer chaque bateau assez longtemps pour qu'il rentre au port. Faites rentrer tous les bateaux pour gagner la nuit ; un bateau qui touche les rochers termine la partie.","slug":"le-gardien-du-phare","style":"risograph","title":"Le Gardien du Phare"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Gardien du Phare</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #fbf7ee; overflow: hidden;
11|     touch-action: none;
12|     font-family: 'Arial Narrow', Arial, sans-serif;
13|   }
14|   #wrap { position: fixed; inset: 0; }
15|   canvas { display: block; width: 100%; height: 100%; touch-action: none; }
16| </style>
17| </head>
18| <body>
19| <div id="wrap">
20| <canvas id="game"></canvas>
21| </div>
22| <script>
23| // ---- Bridge helper (verbatim) ----
24| const CARTRIDGE = {
25|   send(type, payload = {}) {
26|     window.parent.postMessage(
27|       { source: "cartridge", v: 1, type, payload },
28|       "*",
29|     );
30|   },
31| };
32| </script>
33| <script>
34| (function(){
35|   const canvas = document.getElementById('game');
36|   const ctx = canvas.getContext('2d');
37| 
38|   const PAPER = '#fbf7ee';
39|   const INK1 = '#ff48b0';
40|   const INK2 = '#0078bf';
41|   const OVER = '#5b3a8c';
42| 
43|   let DPR = Math.max(1, window.devicePixelRatio || 1);
44|   let W = 0, H = 0;
45| 
46|   function resize() {
47|     DPR = Math.max(1, window.devicePixelRatio || 1);
48|     W = window.innerWidth;
49|     H = window.innerHeight;
50|     canvas.width = Math.floor(W * DPR);
51|     canvas.height = Math.floor(H * DPR);
52|     canvas.style.width = W + 'px';
53|     canvas.style.height = H + 'px';
54|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
55|     buildGrainTile();
56|   }
57| 
58|   // ---- Grain tile (pre-rendered noise) ----
59|   let grainCanvas = document.createElement('canvas');
60|   let grainCtx = grainCanvas.getContext('2d');
61|   function buildGrainTile() {
62|     const size = 128;
63|     grainCanvas.width = size;
64|     grainCanvas.height = size;
65|     const imgData = grainCtx.createImageData(size, size);
66|     for (let i = 0; i < imgData.data.length; i += 4) {
67|       const v = Math.random() * 255;
68|       imgData.data[i] = v;
69|       imgData.data[i+1] = v;
70|       imgData.data[i+2] = v;
71|       imgData.data[i+3] = 255;
72|     }
73|     grainCtx.putImageData(imgData, 0, 0);
74|   }
75|   let grainPattern = null;
76| 
77|   function drawGrain() {
78|     if (!grainPattern) {
79|       grainPattern = ctx.createPattern(grainCanvas, 'repeat');
80|     }
81|     ctx.save();
82|     ctx.globalAlpha = 0.08;
83|     ctx.fillStyle = grainPattern;
84|     ctx.fillRect(0, 0, W, H);
85|     ctx.restore();
86|   }
87| 
88|   // ---- Game state ----
89|   let paused = false;
90|   let screen = 'title'; // title, playing, stageclear, win, lose
91|   let stage = 0;
92|   let score = 0;
93|   let started = false;
94| 
95|   const STAGES = [
96|     { boats: 2, speed: 0.10, needLight: 1.6, rockDelay: 5.0 },
97|     { boats: 3, speed: 0.13, needLight: 1.8, rockDelay: 4.5 },
98|     { boats: 4, speed: 0.16, needLight: 2.0, rockDelay: 4.0 },
99|     { boats: 5, speed: 0.19, needLight: 2.2, rockDelay: 3.6 },
100|     { boats: 6, speed: 0.22, needLight: 2.4, rockDelay: 3.2 }
101|   ];
102| 
103|   let cx = 0, cy = 0; // lighthouse center
104|   let beamAngle = 0; // radians
105|   let targetAngle = 0;
106|   let beamWidth = 0.32; // radians half-angle-ish (full spread)
107|   let beamLength = 0;
108| 
109|   let boats = [];
110|   let stageGoalTimer = 0; // grace period
111|   let graceSeconds = 3;
112|   let stageStartMsg = '';
113|   let stageStartMsgTimer = 0;
114| 
115|   let held = false;
116| 
117|   function toCanvas(evt) {
118|     const rect = canvas.getBoundingClientRect();
119|     const x = (evt.clientX - rect.left);
120|     const y = (evt.clientY - rect.top);
121|     return { x, y };
122|   }
123| 
124|   function angleFromPoint(p) {
125|     return Math.atan2(p.y - cy, p.x - cx);
126|   }
127| 
128|   canvas.addEventListener('pointerdown', (event) => {
129|     if (screen !== 'playing') return;
130|     held = true;
131|     canvas.setPointerCapture(event.pointerId);
132|     targetAngle = angleFromPoint(toCanvas(event));
133|   });
134|   canvas.addEventListener('pointermove', (event) => {
135|     if (!held) return;
136|     targetAngle = angleFromPoint(toCanvas(event));
137|   });
138|   canvas.addEventListener('pointerup', () => { held = false; });
139|   canvas.addEventListener('pointercancel', () => { held = false; });
140| 
141|   // click on title / end screens to advance
142|   canvas.addEventListener('pointerdown', (event) => {
143|     if (screen === 'title') {
144|       beginPlay();
145|     } else if (screen === 'win' || screen === 'lose') {
146|       backToTitle();
147|     }
148|   }, true);
149| 
150|   function shortestAngleDiff(a, b) {
151|     let d = (b - a) % (Math.PI * 2);
152|     if (d > Math.PI) d -= Math.PI * 2;
153|     if (d < -Math.PI) d += Math.PI * 2;
154|     return d;
155|   }
156| 
157|   function buildStage(n) {
158|     const cfg = STAGES[n - 1];
159|     boats = [];
160|     for (let i = 0; i < cfg.boats; i++) {
161|       spawnBoat(cfg, i);
162|     }
163|     stageGoalTimer = graceSeconds;
164|     stageStartMsg = 'Phase ' + n + ' — Faites rentrer ' + cfg.boats + ' bateaux';
165|     stageStartMsgTimer = 3.2;
166|   }
167| 
168|   function spawnBoat(cfg, idx) {
169|     const angle = Math.random() * Math.PI * 2;
170|     const dist = Math.max(W, H) * 0.62 + Math.random() * 40;
171|     const x = cx + Math.cos(angle) * dist;
172|     const y = cy + Math.sin(angle) * dist;
173|     boats.push({
174|       x, y,
175|       angle: angle,
176|       speed: cfg.speed * (0.85 + Math.random() * 0.3),
177|       lit: 0,
178|       needLight: cfg.needLight,
179|       rockDelay: cfg.rockDelay,
180|       dangerTimer: 0,
181|       safe: false,
182|       dead: false,
183|       bob: Math.random() * Math.PI * 2
184|     });
185|   }
186| 
187|   function enterStage(next) {
188|     stage = next;
189|     buildStage(stage);
190|     CARTRIDGE.send('level', { index: stage });
191|     screen = 'playing';
192|   }
193| 
194|   function onGoalMet() {
195|     if (stage === STAGES.length) {
196|       screen = 'win';
197|       CARTRIDGE.send('end', { reason: 'win', value: score });
198|     } else {
199|       enterStage(stage + 1);
200|     }
201|   }
202| 
203|   function onStageFailed() {
204|     screen = 'lose';
205|     CARTRIDGE.send('end', { reason: 'lose', value: score });
206|   }
207| 
208|   function beginPlay() {
209|     if (!started) {
210|       started = true;
211|       CARTRIDGE.send('start');
212|     }
213|     score = 0;
214|     CARTRIDGE.send('score', { value: score });
215|     enterStage(1);
216|   }
217| 
218|   function backToTitle() {
219|     screen = 'title';
220|     boats = [];
221|     stage = 0;
222|     score = 0;
223|   }
224| 
225|   // ---- Update ----
226|   let lastTime = performance.now();
227|   function update(dt) {
228|     if (screen !== 'playing') return;
229| 
230|     // ease beam angle toward target
231|     const diff = shortestAngleDiff(beamAngle, targetAngle);
232|     beamAngle += diff * Math.min(1, dt * 6);
233| 
234|     if (stageGoalTimer > 0) stageGoalTimer -= dt;
235|     if (stageStartMsgTimer > 0) stageStartMsgTimer -= dt;
236| 
237|     const rockRadius = Math.min(W, H) * 0.14;
238|     const portRadius = Math.min(W, H) * 0.10;
239| 
240|     let allSafe = true;
241|     for (const boat of boats) {
242|       if (boat.safe || boat.dead) continue;
243|       allSafe = false;
244| 
245|       // move boat toward lighthouse slowly (drifting toward rocks)
246|       const dx = cx - boat.x, dy = cy - boat.y;
247|       const dist = Math.sqrt(dx*dx + dy*dy);
248|       const nx = dx / (dist || 1), ny = dy / (dist || 1);
249|       boat.bob += dt * 2;
250| 
251|       // Check if boat is lit by beam
252|       const boatAngle = Math.atan2(boat.y - cy, boat.x - cx);
253|       const adiff = Math.abs(shortestAngleDiff(beamAngle, boatAngle));
254|       const isLit = adiff < beamWidth * 0.5 && dist < beamLength;
255| 
256|       if (isLit) {
257|         boat.lit += dt;
258|       } else {
259|         boat.lit = Math.max(0, boat.lit - dt * 0.5);
260|       }
261| 
262|       if (stageGoalTimer <= 0) {
263|         if (!isLit) {
264|           boat.dangerTimer += dt;
265|         } else {
266|           boat.dangerTimer = Math.max(0, boat.dangerTimer - dt * 1.5);
267|         }
268|       }
269| 
270|       // drift toward rocks always (slowly), guided in when lit enough
271|       let driftSpeed = boat.speed * 0.4;
272|       if (boat.lit >= boat.needLight) {
273|         driftSpeed = boat.speed * 1.4; // guided in fast once "saved"
274|       }
275|       boat.x += nx * driftSpeed * 60 * dt * 0.5;
276|       boat.y += ny * driftSpeed * 60 * dt * 0.5;
277| 
278|       if (boat.lit >= boat.needLight && dist < portRadius) {
279|         boat.safe = true;
280|         score += 10;
281|         CARTRIDGE.send('score', { value: score });
282|       }
283| 
284|       if (dist < rockRadius && boat.lit < boat.needLight) {
285|         boat.dead = true;
286|         onStageFailed();
287|         return;
288|       }
289| 
290|       if (stageGoalTimer <= 0 && boat.dangerTimer > boat.rockDelay) {
291|         boat.dead = true;
292|         onStageFailed();
293|         return;
294|       }
295|     }
296| 
297|     if (allSafe && boats.length > 0) {
298|       onGoalMet();
299|     }
300|   }
301| 
302|   // ---- Draw ----
303|   function drawTitle() {
304|     ctx.fillStyle = PAPER;
305|     ctx.fillRect(0, 0, W, H);
306|     drawHalftoneSea();
307|     drawLighthouseBase();
308| 
309|     ctx.fillStyle = INK1;
310|     ctx.textAlign = 'center';
311|     ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.075) + 'px Arial Narrow, Arial, sans-serif';
312|     ctx.fillText('LE GARDIEN', W/2, H*0.28);
313|     ctx.fillStyle = INK2;
314|     ctx.fillText('DU PHARE', W/2 + 2, H*0.28 + Math.round(Math.min(W,H)*0.075) + 4);
315| 
316|     ctx.fillStyle = OVER;
317|     ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.03) + 'px Arial Narrow, Arial, sans-serif';
318|     ctx.fillText('Glissez pour tourner le faisceau', W/2, H*0.62);
319|     ctx.fillText('et guidez les bateaux au port', W/2, H*0.62 + Math.round(Math.min(W,H)*0.045));
320| 
321|     ctx.fillStyle = INK1;
322|     ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.045) + 'px Arial Narrow, Arial, sans-serif';
323|     ctx.fillText('TOUCHEZ POUR COMMENCER', W/2, H*0.8);
324|   }
325| 
326|   function drawHalftoneSea() {
327|     ctx.save();
328|     ctx.fillStyle = INK2;
329|     ctx.globalAlpha = 1;
330|     const spacing = Math.max(14, Math.min(W,H)*0.03);
331|     for (let y = H*0.5; y < H; y += spacing) {
332|       for (let x = 0; x < W; x += spacing) {
333|         const t = (y - H*0.5) / (H*0.5);
334|         const r = spacing * 0.15 * (0.3 + t * 0.7);
335|         ctx.beginPath();
336|         ctx.arc(x + ((Math.floor(y/spacing)%2)? spacing/2:0), y, r, 0, Math.PI*2);
337|         ctx.fill();
338|       }
339|     }
340|     ctx.restore();
341|   }
342| 
343|   function drawLighthouseBase() {
344|     ctx.save();
345|     ctx.translate(cx, cy);
346|     // rocks
347|     ctx.fillStyle = OVER;
348|     ctx.beginPath();
349|     const rockR = Math.min(W, H) * 0.14;
350|     for (let i = 0; i < 10; i++) {
351|       const a = (i / 10) * Math.PI * 2;
352|       const rr = rockR * (0.85 + 0.15 * Math.sin(i * 3.1));
353|       const px = Math.cos(a) * rr, py = Math.sin(a) * rr;
354|       if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
355|     }
356|     ctx.closePath();
357|     ctx.fill();
358| 
359|     // tower
360|     ctx.fillStyle = INK1;
361|     const towerW = Math.min(W,H) * 0.09;
362|     const towerH = Math.min(W,H) * 0.16;
363|     ctx.fillRect(-towerW/2, -towerH/2, towerW, towerH);
364|     ctx.fillStyle = INK2;
365|     ctx.fillRect(-towerW/2+2, -towerH/2+2, towerW, towerH*0.35);
366|     // top
367|     ctx.fillStyle = OVER;
368|     ctx.beginPath();
369|     ctx.moveTo(-towerW*0.6, -towerH/2);
370|     ctx.lineTo(towerW*0.6, -towerH/2);
371|     ctx.lineTo(0, -towerH/2 - towerW*0.7);
372|     ctx.closePath();
373|     ctx.fill();
374|     ctx.restore();
375|   }
376| 
377|   function drawBeam() {
378|     ctx.save();
379|     ctx.translate(cx, cy);
380|     ctx.rotate(beamAngle);
381|     const grad = ctx.createLinearGradient(0, 0, beamLength, 0);
382|     grad.addColorStop(0, 'rgba(255,72,176,0.55)');
383|     grad.addColorStop(1, 'rgba(255,72,176,0.03)');
384|     ctx.fillStyle = grad;
385|     ctx.beginPath();
386|     ctx.moveTo(0, 0);
387|     ctx.arc(0, 0, beamLength, -beamWidth/2, beamWidth/2);
388|     ctx.closePath();
389|     ctx.fill();
390|     ctx.restore();
391|   }
392| 
393|   function drawBoat(boat) {
394|     ctx.save();
395|     ctx.translate(boat.x, boat.y + Math.sin(boat.bob) * 2);
396|     const ang = Math.atan2(cy - boat.y, cx - boat.x);
397|     ctx.rotate(ang + Math.PI/2);
398|     const s = Math.min(W,H) * 0.018;
399|     const litFrac = Math.min(1, boat.lit / boat.needLight);
400|     ctx.fillStyle = litFrac > 0.99 ? OVER : (litFrac > 0 ? INK2 : INK1);
401|     ctx.beginPath();
402|     ctx.moveTo(0, -s*1.4);
403|     ctx.lineTo(s, s);
404|     ctx.lineTo(-s, s);
405|     ctx.closePath();
406|     ctx.fill();
407| 
408|     // danger flash
409|     if (boat.dangerTimer > 0) {
410|       ctx.globalAlpha = 0.5 + 0.5 * Math.sin(performance.now()/80);
411|       ctx.strokeStyle = INK1;
412|       ctx.lineWidth = 2;
413|       ctx.beginPath();
414|       ctx.arc(0, 0, s*2.2, 0, Math.PI*2);
415|       ctx.stroke();
416|       ctx.globalAlpha = 1;
417|     }
418|     ctx.restore();
419| 
420|     // light meter above boat
421|     if (!boat.safe) {
422|       const barW = s * 3;
423|       ctx.save();
424|       ctx.translate(boat.x - barW/2, boat.y - s*3);
425|       ctx.fillStyle = '#00000022';
426|       ctx.fillRect(0, 0, barW, 4);
427|       ctx.fillStyle = INK2;
428|       ctx.fillRect(0, 0, barW * Math.min(1, boat.lit/boat.needLight), 4);
429|       ctx.restore();
430|     }
431|   }
432| 
433|   function drawPlaying() {
434|     ctx.fillStyle = PAPER;
435|     ctx.fillRect(0, 0, W, H);
436|     drawHalftoneSea();
437|     drawBeam();
438|     drawLighthouseBase();
439| 
440|     for (const boat of boats) {
441|       if (boat.dead) continue;
442|       drawBoat(boat);
443|     }
444| 
445|     // HUD
446|     ctx.textAlign = 'left';
447|     ctx.fillStyle = INK2;
448|     ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.035) + 'px Arial Narrow, Arial, sans-serif';
449|     ctx.fillText('Phase ' + stage, 14, 30);
450|     ctx.fillStyle = OVER;
451|     ctx.fillText('Score ' + score, 14, 56);
452| 
453|     if (stageStartMsgTimer > 0) {
454|       ctx.textAlign = 'center';
455|       ctx.fillStyle = INK1;
456|       ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.04) + 'px Arial Narrow, Arial, sans-serif';
457|       ctx.fillText(stageStartMsg, W/2, H*0.15);
458|     }
459| 
460|     if (paused) {
461|       ctx.fillStyle = 'rgba(0,0,0,0.35)';
462|       ctx.fillRect(0,0,W,H);
463|       ctx.fillStyle = PAPER;
464|       ctx.textAlign = 'center';
465|       ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.06) + 'px Arial Narrow, Arial, sans-serif';
466|       ctx.fillText('PAUSE', W/2, H/2);
467|     }
468|   }
469| 
470|   function drawEnd(win) {
471|     ctx.fillStyle = PAPER;
472|     ctx.fillRect(0, 0, W, H);
473|     drawHalftoneSea();
474|     drawLighthouseBase();
475| 
476|     ctx.textAlign = 'center';
477|     ctx.fillStyle = win ? INK2 : INK1;
478|     ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.07) + 'px Arial Narrow, Arial, sans-serif';
479|     ctx.fillText(win ? 'NUIT SAUVÉE !' : 'NAUFRAGE...', W/2, H*0.4);
480| 
481|     ctx.fillStyle = OVER;
482|     ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.04) + 'px Arial Narrow, Arial, sans-serif';
483|     ctx.fillText('Score final : ' + score, W/2, H*0.5);
484| 
485|     ctx.fillStyle = INK1;
486|     ctx.font = 'bold ' + Math.round(Math.min(W,H)*0.035) + 'px Arial Narrow, Arial, sans-serif';
487|     ctx.fillText('Touchez pour recommencer', W/2, H*0.65);
488|   }
489| 
490|   function draw() {
491|     if (screen === 'title') drawTitle();
492|     else if (screen === 'playing') drawPlaying();
493|     else if (screen === 'win') drawEnd(true);
494|     else if (screen === 'lose') drawEnd(false);
495|     drawGrain();
496|   }
497| 
498|   function loop(now) {
499|     const dt = Math.min(0.05, (now - lastTime) / 1000);
500|     lastTime = now;
501|     if (!paused) {
502|       update(dt);
503|     }
504|     draw();
505|     requestAnimationFrame(loop);
506|   }
507| 
508|   function layout() {
509|     resize();
510|     cx = W / 2;
511|     cy = H * 0.42;
512|     beamLength = Math.max(W, H) * 0.75;
513|   }
514| 
515|   window.addEventListener('resize', layout);
516| 
517|   window.addEventListener('message', (event) => {
518|     const data = event.data;
519|     if (!data || data.source !== 'cartridge-host') return;
520|     if (data.type === 'pause') paused = true;
521|     if (data.type === 'resume') paused = false;
522|     if (data.type === 'reset') backToTitle();
523|   });
524| 
525|   layout();
526|   targetAngle = beamAngle = -Math.PI/2;
527| 
528|   CARTRIDGE.send('boot', { title: 'Le Gardien du Phare', gameType: 'stage-clear', lang: 'fr' });
529| 
530|   requestAnimationFrame((t) => { lastTime = t; requestAnimationFrame(loop); });
531| })();
532| </script>
533| </body>
534| </html>
535|

